#### Phase 2: Configure API Gateway for Version Routing

**Step 4: Implement Version Routing**

Configure API gateway to route based on version in path:

```yaml
# Kong Gateway Configuration Example
# Route v1 requests to v1 upstream

routes:

  - name: claims-api-v1
    protocols:
      - https
    paths:
      - /v1/claims
    strip_path: false
    methods:
      - GET
      - POST
      - PUT
      - DELETE
    service:
      name: claims-service-v1
      url: http://claims-v1.internal:8080

  - name: claims-api-v2
    protocols:
      - https
    paths:
      - /v2/claims
    strip_path: false
    methods:
      - GET
      - POST
      - PUT
      - DELETE
    service:
      name: claims-service-v2
      url: http://claims-v2.internal:8080

services:

  - name: claims-service-v1
    url: http://claims-v1.internal:8080
    connect_timeout: 5000
    read_timeout: 30000
    retries: 3

  - name: claims-service-v2
    url: http://claims-v2.internal:8080
    connect_timeout: 5000
    read_timeout: 30000
    retries: 3
```

**Step 5: Add Version Lifecycle Enforcement Plugin**

Implement custom plugin or use existing capability to enforce lifecycle:

```javascript
// Kong Plugin: Version Lifecycle Enforcer
// Checks version status and adds appropriate headers/responses

const axios = require('axios');

async function checkVersionLifecycle(version) {
  // Query API registry for version lifecycle status
  const response = await axios.get(
    `http://api-registry/api/versions/claims-api/${version}`
  );
  return response.data;
}

class VersionLifecyclePlugin {
  async access(kong) {
    // Extract version from path
    const path = kong.request.get_path();
    const versionMatch = path.match(/\/v(\d+)\//);

    if (!versionMatch) {
      return kong.response.exit(400, {
        error: 'Version required in path: /v{version}/'
      });
    }

    const version = `v${versionMatch[1]}`;
    const lifecycle = await checkVersionLifecycle(version);

    // Handle sunset versions
    if (lifecycle.status === 'sunset') {
      return kong.response.exit(410, {
        error: `API ${version} was sunset on ${lifecycle.sunset_date}`,
        message: 'This API version is no longer available',
        migration_guide: lifecycle.migration_guide_url,
        current_version: lifecycle.current_version
      });
    }

    // Add warning header for deprecated versions
    if (lifecycle.status === 'deprecated') {
      kong.response.set_header(
        'Warning',
        `299 - "API ${version} is deprecated and will be sunset on ${lifecycle.sunset_date}. ` +
        `Please migrate to ${lifecycle.current_version}. Migration guide: ${lifecycle.migration_guide_url}"`
      );
      kong.response.set_header('X-API-Deprecation-Date', lifecycle.sunset_date);
      kong.response.set_header('X-API-Sunset-Date', lifecycle.sunset_date);
    }

    // Add version header to all responses
    kong.response.set_header('X-API-Version', lifecycle.full_version);
    kong.response.set_header('X-API-Status', lifecycle.status);
  }
}

module.exports = VersionLifecyclePlugin;
```

**Step 6: Configure Version-Specific Monitoring**

Set up monitoring to track metrics by version:

```yaml
# Datadog Dashboard Configuration
# API Version Health Dashboard

dashboards:

  - title: "API Version Distribution"
    widgets:
      - type: timeseries
        title: "Requests by Version"
        query: "sum:api.requests{*} by {api_version}"

      - type: query_value
        title: "v1 (Deprecated) Traffic %"
        query: "sum:api.requests{api_version:v1}/sum:api.requests{*}*100"
        precision: 1

      - type: query_value
        title: "v2 (Supported) Traffic %"
        query: "sum:api.requests{api_version:v2}/sum:api.requests{*}*100"
        precision: 1

      - type: query_value
        title: "v3 (Current) Traffic %"
        query: "sum:api.requests{api_version:v3}/sum:api.requests{*}*100"
        precision: 1

monitors:

  - name: "Deprecated Version High Usage Alert"
    type: metric_alert
    query: "avg(last_1d):sum:api.requests{api_version:v1}/sum:api.requests{*} > 0.10"
    message: |
      Deprecated version v1 still receiving >10% of traffic 30 days from sunset.

      Current v1 traffic: {{value}}%
      Sunset date: {{sunset_date}}
      Days remaining: {{days_until_sunset}}

      Action Required: Contact consumers still on v1 and provide migration support.

  - name: "Sunset Version Receiving Requests"
    type: metric_alert
    query: "sum(last_5m):api.requests{api_version:v1,status_code:410} > 10"
    message: |
      Sunset version v1 receiving requests returning 410 Gone.

      This indicates consumers have not completed migration.
      Immediate outreach required to affected consumers.
```

