#### Phase 3: Implement Version-Specific Code Patterns

**Step 7: Structure Code for Multiple Versions**

Organize code to support multiple versions cleanly:

```csharp
// ASP.NET Core API Structure

// Shared domain models and business logic
namespace ClaimsService.Domain
{
    public class Claim
    {
        public string ClaimId { get; set; }
        public DateTime ServiceDate { get; set; }
        public decimal Amount { get; set; }
        public string Status { get; set; }
        // ... complete domain model
    }

    public interface IClaimService
    {
        Task<Claim> GetClaimAsync(string claimId);
        Task<Claim> SubmitClaimAsync(Claim claim);
    }
}

// V1 API Controllers and DTOs
namespace ClaimsService.V1.Controllers
{
    [ApiController]
    [Route("v1/claims")]
    public class ClaimsController : ControllerBase
    {
        private readonly IClaimService _claimService;

        [HttpGet("{claimId}")]
        public async Task<ActionResult<V1ClaimResponse>> GetClaim(string claimId)
        {
            var claim = await _claimService.GetClaimAsync(claimId);
            var response = MapToV1Response(claim);

            Response.Headers.Add("X-API-Version", "1.2.4");
            return Ok(response);
        }

        private V1ClaimResponse MapToV1Response(Claim claim)
        {
            // V1 schema mapping
            return new V1ClaimResponse
            {
                claim_id = claim.ClaimId,  // V1 uses snake_case
                service_date = claim.ServiceDate.ToString("yyyy-MM-dd"),
                amount = claim.Amount,
                status = claim.Status
            };
        }
    }

    public class V1ClaimResponse
    {
        public string claim_id { get; set; }
        public string service_date { get; set; }
        public decimal amount { get; set; }
        public string status { get; set; }
    }
}

// V2 API Controllers and DTOs
namespace ClaimsService.V2.Controllers
{
    [ApiController]
    [Route("v2/claims")]
    public class ClaimsController : ControllerBase
    {
        private readonly IClaimService _claimService;

        [HttpGet("{claimId}")]
        public async Task<ActionResult<V2ClaimResponse>> GetClaim(string claimId)
        {
            var claim = await _claimService.GetClaimAsync(claimId);
            var response = MapToV2Response(claim);

            Response.Headers.Add("X-API-Version", "2.1.0");
            return Ok(response);
        }

        private V2ClaimResponse MapToV2Response(Claim claim)
        {
            // V2 schema mapping
            return new V2ClaimResponse
            {
                ClaimId = claim.ClaimId,  // V2 uses PascalCase
                ServiceDate = claim.ServiceDate,  // V2 returns ISO 8601
                Amount = claim.Amount,
                Status = claim.Status,
                // V2 added nested metadata object
                Metadata = new ClaimMetadata
                {
                    CreatedAt = claim.CreatedAt,
                    UpdatedAt = claim.UpdatedAt
                }
            };
        }
    }

    public class V2ClaimResponse
    {
        public string ClaimId { get; set; }
        public DateTime ServiceDate { get; set; }
        public decimal Amount { get; set; }
        public string Status { get; set; }
        public ClaimMetadata Metadata { get; set; }  // New in v2
    }

    public class ClaimMetadata
    {
        public DateTime CreatedAt { get; set; }
        public DateTime UpdatedAt { get; set; }
    }
}
```
